export const THROTTLE_CONTROL={minimum:.20};
export function throttleAt(clientY,rect){return THROTTLE_CONTROL.minimum+(1-THROTTLE_CONTROL.minimum)*Math.max(0,Math.min(1,(rect.top+rect.height-clientY)/rect.height));}
export function bindThrottle(button,onChange){let pointer=null;const set=value=>{onChange(value);button.style.setProperty('--throttle',String(value));button.setAttribute('aria-valuenow',String(Math.round(value*100)));button.querySelector?.('.gas-value')&&(button.querySelector('.gas-value').textContent=Math.round(value*100)+'%');};const move=e=>{set(throttleAt(e.clientY,button.getBoundingClientRect()));e.preventDefault();};const reset=()=>{pointer=null;set(0);button.classList.remove('active');};button.addEventListener('pointerdown',e=>{if(pointer!==null)return;pointer=e.pointerId;button.setPointerCapture(pointer);button.classList.add('active');move(e);});button.addEventListener('pointermove',e=>{if(pointer===e.pointerId)move(e);});for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,e=>{if(pointer===e.pointerId)reset();});return reset;}
